// src/Product.js

import React, {
    useEffect,
    useMemo,
    useState,
} from "react";

import {
    Link,
    useNavigate,
    useParams,
    useSearchParams,
} from "react-router-dom";

import {
    AnimatePresence,
    motion,
} from "framer-motion";

import "./App.css";

import { useCart } from "./CartContext";
import { PRODUCTS, asset } from "./productsData";
import SiteHeader from "./SiteHeader";

export default function Product() {
    const { addItem } = useCart();

    const navigate = useNavigate();
    const { productId } = useParams();

    const [
        searchParams,
        setSearchParams,
    ] = useSearchParams();

    const product = useMemo(() => {
        return (
            PRODUCTS.find(
                (item) => item.id === productId
            ) || PRODUCTS[0]
        );
    }, [productId]);

    const gallery = product.gallery || [];
    const requestedView = searchParams.get("view");

    const requestedIndex = useMemo(() => {
        const index = gallery.findIndex(
            (item) => item.id === requestedView
        );

        return index >= 0 ? index : 0;
    }, [gallery, requestedView]);

    const [
        activeImage,
        setActiveImage,
    ] = useState(requestedIndex);

    useEffect(() => {
        setActiveImage(requestedIndex);
    }, [
        requestedIndex,
        product.id,
    ]);

    useEffect(() => {
        window.scrollTo({
            top: 0,
            left: 0,
            behavior: "auto",
        });
    }, [product.id]);

    const activeGalleryItem =
        gallery[activeImage] || gallery[0];

    const savings = Math.max(
        0,
        Number(product.compareAt) -
        Number(product.price)
    );

    const suggestedProducts =
        PRODUCTS.filter(
            (item) => item.id !== product.id
        );

    const selectImage = (index) => {
        const nextImage = gallery[index];

        if (!nextImage) return;

        setActiveImage(index);

        setSearchParams(
            {
                view: nextImage.id,
            },
            {
                replace: true,
            }
        );
    };

    const handleAddToCart = () => {
        addItem({
            id: `ideal-${product.id}`,
            productId: product.id,
            sku: product.sku,
            title:
                product.name ||
                product.productTitle,
            variant: product.label,
            price: Number(product.price),
            image:
                gallery[0]?.src ||
                product.suggestionImage,
        });
    };

    const handleSuggestedView = (
        targetId
    ) => {
        navigate(
            `/product/${targetId}?view=front`
        );

        window.scrollTo({
            top: 0,
            left: 0,
            behavior: "smooth",
        });
    };

    if (!activeGalleryItem) {
        return (
            <div className="page product-page">
                <SiteHeader overlay />

                <main className="product-main">
                    <div className="container">
                        <p>
                            No product images were found.
                        </p>
                    </div>
                </main>
            </div>
        );
    }

    return (
        <div
            className={`page product-page ${product.accent || ""
                }`}
            style={{
                background:
                    product.gradient ||
                    "radial-gradient(circle at top, #292929, #050505 60%, #000)",
            }}
        >
            <SiteHeader overlay />

            <div className="tech-grid-overlay product-grid" />

            <main className="product-main">
                <div className="container product-shell">
                    <section
                        className="product-gallery"
                        aria-label="IDEAL product gallery"
                    >
                        <div className="product-media glass-card">
                            <AnimatePresence mode="wait">
                                <motion.img
                                    key={`${product.id}-${activeGalleryItem.id}`}
                                    src={asset(
                                        activeGalleryItem.src
                                    )}
                                    alt={
                                        activeGalleryItem.alt ||
                                        activeGalleryItem.title
                                    }
                                    className="product-hero-img"
                                    initial={{
                                        opacity: 0,
                                        scale: 0.985,
                                        filter:
                                            "blur(10px)",
                                    }}
                                    animate={{
                                        opacity: 1,
                                        scale: 1,
                                        filter:
                                            "blur(0px)",
                                    }}
                                    exit={{
                                        opacity: 0,
                                        scale: 1.015,
                                        filter:
                                            "blur(10px)",
                                    }}
                                    transition={{
                                        duration: 0.35,
                                        ease: [
                                            0.22,
                                            1,
                                            0.36,
                                            1,
                                        ],
                                    }}
                                />
                            </AnimatePresence>

                            <div className="product-glow" />

                            <div className="product-image-label">
                                <span>
                                    {
                                        activeGalleryItem.title
                                    }
                                </span>

                                <small>
                                    {activeImage + 1}
                                    {" / "}
                                    {gallery.length}
                                </small>
                            </div>
                        </div>

                        <div
                            className="product-thumbs product-thumbs-eight"
                            role="list"
                            aria-label="Choose a product view"
                        >
                            {gallery.map(
                                (item, index) => (
                                    <button
                                        key={item.id}
                                        type="button"
                                        role="listitem"
                                        className={`thumb ${index ===
                                                activeImage
                                                ? "active"
                                                : ""
                                            }`}
                                        aria-label={`Open ${item.title}`}
                                        aria-pressed={
                                            index ===
                                            activeImage
                                        }
                                        onClick={() =>
                                            selectImage(
                                                index
                                            )
                                        }
                                    >
                                        <img
                                            src={asset(
                                                item.src
                                            )}
                                            alt=""
                                            loading="lazy"
                                        />

                                        <span>
                                            {item.shortTitle ||
                                                item.title}
                                        </span>
                                    </button>
                                )
                            )}
                        </div>

                        <div className="product-mini-specs">
                            {(product.bullets || []).map(
                                (text) => (
                                    <div
                                        key={text}
                                        className="mini-pill"
                                    >
                                        <span className="mini-dot" />

                                        <span>
                                            {text}
                                        </span>
                                    </div>
                                )
                            )}
                        </div>

                        {suggestedProducts.length >
                            0 && (
                                <div className="product-suggestions">
                                    <p className="suggestions-title">
                                        Recommended styles
                                    </p>

                                    <div className="suggestions-grid">
                                        {suggestedProducts.map(
                                            (item) => (
                                                <article
                                                    key={
                                                        item.id
                                                    }
                                                    className="suggestion-card glass-card"
                                                >
                                                    <img
                                                        src={asset(
                                                            item.suggestionImage
                                                        )}
                                                        alt={
                                                            item.label
                                                        }
                                                        loading="lazy"
                                                    />

                                                    <div className="suggestion-body">
                                                        <h4>
                                                            {
                                                                item.label
                                                            }
                                                        </h4>

                                                        <p>
                                                            {
                                                                item.suggestionDesc
                                                            }
                                                        </p>

                                                        <div className="suggestion-meta">
                                                            <span>
                                                                $
                                                                {
                                                                    item.price
                                                                }
                                                            </span>

                                                            <button
                                                                type="button"
                                                                className="suggestion-view"
                                                                onClick={() =>
                                                                    handleSuggestedView(
                                                                        item.id
                                                                    )
                                                                }
                                                            >
                                                                View
                                                            </button>
                                                        </div>
                                                    </div>
                                                </article>
                                            )
                                        )}
                                    </div>
                                </div>
                            )}
                    </section>

                    <section className="product-info">
                        <motion.div
                            className="product-info-card glass-card"
                            initial={{
                                opacity: 0,
                                y: 18,
                                filter:
                                    "blur(10px)",
                            }}
                            animate={{
                                opacity: 1,
                                y: 0,
                                filter:
                                    "blur(0px)",
                            }}
                            transition={{
                                duration: 0.5,
                                ease: [
                                    0.22,
                                    1,
                                    0.36,
                                    1,
                                ],
                            }}
                        >
                            <p className="eyebrow">
                                PRODUCT · {product.sku}
                            </p>

                            <h1 className="product-title">
                                {(
                                    product.productTitle ||
                                    product.name ||
                                    product.label
                                )
                                    .split(" ")[0]}{" "}

                                <span>
                                    {(
                                        product.productTitle ||
                                        product.name ||
                                        product.label
                                    )
                                        .split(" ")
                                        .slice(1)
                                        .join(" ")}
                                </span>
                            </h1>

                            <p className="product-tagline">
                                {
                                    product.productTagline
                                }
                            </p>

                            <div className="product-rating">
                                <span className="stars">
                                    ★★★★★
                                </span>

                                <span className="rating-text">
                                    {product.rating || "4.9"}
                                    {" · "}
                                    {product.reviews || "128"}
                                    {" reviews"}
                                </span>
                            </div>

                            <div className="product-price-row">
                                <div className="price">
                                    <span className="now">
                                        ${product.price}
                                    </span>

                                    <span className="was">
                                        $
                                        {
                                            product.compareAt
                                        }
                                    </span>
                                </div>

                                {savings > 0 && (
                                    <div className="save">
                                        Save ${savings}
                                    </div>
                                )}
                            </div>

                            <div className="product-variants">
                                <p className="variant-label">
                                    Style
                                </p>

                                <div className="variant-buttons">
                                    {PRODUCTS.map(
                                        (variant) => (
                                            <button
                                                key={
                                                    variant.id
                                                }
                                                type="button"
                                                className={`variant-btn ${variant.id ===
                                                        product.id
                                                        ? "active"
                                                        : ""
                                                    }`}
                                                onClick={() => {
                                                    navigate(
                                                        `/product/${variant.id}?view=front`
                                                    );

                                                    window.scrollTo(
                                                        {
                                                            top: 0,
                                                            behavior:
                                                                "smooth",
                                                        }
                                                    );
                                                }}
                                            >
                                                <span
                                                    className="variant-swatch"
                                                    style={{
                                                        background:
                                                            variant.swatch ||
                                                            "#1b1b1b",
                                                    }}
                                                />

                                                {
                                                    variant.label
                                                }
                                            </button>
                                        )
                                    )}
                                </div>
                            </div>

                            <div className="selected-view-copy">
                                <span>
                                    {
                                        activeGalleryItem.title
                                    }
                                </span>

                                <p>
                                    {
                                        activeGalleryItem.description
                                    }
                                </p>
                            </div>

                            <div className="product-actions">
                                <button
                                    type="button"
                                    className="primary-cta product-buy"
                                    onClick={
                                        handleAddToCart
                                    }
                                >
                                    Pre-order now
                                </button>

                                <Link
                                    to="/specs"
                                    className="secondary-cta product-specs"
                                >
                                    View specs
                                </Link>
                            </div>

                            <div className="product-shipping">
                                <div className="ship-item">
                                    <span className="ship-icon">
                                        ✓
                                    </span>

                                    30-day comfort guarantee
                                </div>

                                <div className="ship-item">
                                    <span className="ship-icon">
                                        ✓
                                    </span>

                                    Worldwide shipping
                                </div>

                                <div className="ship-item">
                                    <span className="ship-icon">
                                        ✓
                                    </span>

                                    Secure checkout
                                </div>
                            </div>
                        </motion.div>

                        <div
                            className="product-details"
                            id="details"
                        >
                            <div className="detail-card glass-card">
                                <h3>
                                    {product.detailTitle ||
                                        "Designed for daily clarity"}
                                </h3>

                                <p>
                                    {product.detailDesc ||
                                        "A lightweight frame designed for balanced comfort, reduced glare, and sharper everyday vision."}
                                </p>
                            </div>

                            <div className="detail-card glass-card">
                                <h3>
                                    What you get
                                </h3>

                                <p>
                                    {(
                                        product.packageIncludes ||
                                        [
                                            "IDEAL frame",
                                            "Protective case",
                                            "Cleaning cloth",
                                            "Premium packaging",
                                        ]
                                    ).join(" · ")}
                                </p>
                            </div>
                        </div>
                    </section>
                </div>
            </main>
        </div>
    );
}