// src/Checkout.js

import React, {
    useEffect,
    useMemo,
    useState,
} from "react";

import { Link } from "react-router-dom";

import "./App.css";

import { useCart } from "./CartContext";
import SiteHeader from "./SiteHeader";

function resolveImage(source) {
    if (!source) return "";

    if (
        source.startsWith("http://") ||
        source.startsWith("https://") ||
        source.startsWith("data:") ||
        source.startsWith("blob:")
    ) {
        return source;
    }

    const normalizedSource =
        source.startsWith("/")
            ? source
            : `/${source}`;

    return `${process.env.PUBLIC_URL}${normalizedSource}`;
}

function CheckoutIntro() {
    const [visible, setVisible] =
        useState(true);

    useEffect(() => {
        const timer = window.setTimeout(
            () => setVisible(false),
            850
        );

        return () => {
            window.clearTimeout(timer);
        };
    }, []);

    if (!visible) return null;

    return (
        <div
            className="checkout-intro"
            aria-hidden="true"
        >
            <div className="checkout-intro-bg" />
            <div className="checkout-intro-glow" />

            <div className="checkout-intro-lock">
                <div className="checkout-lock-shackle" />
                <div className="checkout-lock-body" />
            </div>
        </div>
    );
}

export default function Checkout() {
    const {
        items,
        removeItem,
        updateQuantity,
        clearCart,
        count,
        subtotal,
    } = useCart();

    const [orderComplete, setOrderComplete] =
        useState(false);

    const [formData, setFormData] =
        useState({
            fullName: "",
            email: "",
            phone: "",
            country: "",
            city: "",
            address: "",
            postalCode: "",
            cardName: "",
            cardNumber: "",
            expiry: "",
            cvv: "",
        });

    useEffect(() => {
        window.scrollTo({
            top: 0,
            left: 0,
            behavior: "auto",
        });
    }, []);

    const shipping = 0;

    const total = useMemo(() => {
        return Number(subtotal) + shipping;
    }, [subtotal]);

    const formatPrice = (value) => {
        return `$${Number(value || 0).toFixed(2)}`;
    };

    const handleChange = (event) => {
        const {
            name,
            value,
        } = event.target;

        setFormData((previous) => ({
            ...previous,
            [name]: value,
        }));
    };

    const handleSubmit = (event) => {
        event.preventDefault();

        if (items.length === 0) return;

        setOrderComplete(true);
        clearCart();

        window.scrollTo({
            top: 0,
            behavior: "smooth",
        });
    };

    return (
        <div
            className="page checkout-page"
            style={{
                background:
                    "radial-gradient(circle at top, #292929 0%, #070707 58%, #000 100%)",
            }}
        >
            <CheckoutIntro />

            <SiteHeader overlay />

            <div className="tech-grid-overlay checkout-grid-overlay" />

            <main className="checkout-wrap">
                <div className="container">
                    {orderComplete ? (
                        <section className="checkout-card glass-card">
                            <div className="checkout-heading">
                                <p className="eyebrow">
                                    ORDER RECEIVED
                                </p>

                                <h1 className="checkout-title">
                                    Your pre-order is confirmed.
                                </h1>

                                <p className="checkout-sub">
                                    Thank you for choosing
                                    IDEAL. Your order request
                                    has been received
                                    successfully.
                                </p>
                            </div>

                            <div className="checkout-trust-row">
                                <span className="trust-pill">
                                    <span className="trust-dot" />
                                    Secure request
                                </span>

                                <span className="trust-pill">
                                    <span className="trust-dot" />
                                    Worldwide shipping
                                </span>

                                <span className="trust-pill">
                                    <span className="trust-dot" />
                                    30-day guarantee
                                </span>
                            </div>

                            <div className="cart-bottom">
                                <Link
                                    to="/products"
                                    className="primary-cta"
                                >
                                    Continue shopping
                                </Link>

                                <Link
                                    to="/"
                                    className="secondary-cta"
                                >
                                    Back home
                                </Link>
                            </div>
                        </section>
                    ) : (
                        <div className="checkout-grid-premium">
                            <section className="checkout-card checkout-form-card">
                                <div className="checkout-heading">
                                    <p className="eyebrow">
                                        SECURE CHECKOUT
                                    </p>

                                    <h1 className="checkout-title">
                                        Complete your pre-order.
                                    </h1>

                                    <p className="checkout-sub">
                                        Enter your contact,
                                        shipping, and payment
                                        information below.
                                    </p>
                                </div>

                                <form
                                    className="checkout-form-premium"
                                    onSubmit={
                                        handleSubmit
                                    }
                                >
                                    <h2 className="checkout-section-title">
                                        Contact information
                                    </h2>

                                    <div className="form-group">
                                        <label htmlFor="fullName">
                                            Full name
                                        </label>

                                        <input
                                            id="fullName"
                                            name="fullName"
                                            type="text"
                                            value={
                                                formData.fullName
                                            }
                                            onChange={
                                                handleChange
                                            }
                                            placeholder="Your full name"
                                            autoComplete="name"
                                            required
                                        />
                                    </div>

                                    <div className="form-row">
                                        <div className="form-group">
                                            <label htmlFor="email">
                                                Email address
                                            </label>

                                            <input
                                                id="email"
                                                name="email"
                                                type="email"
                                                value={
                                                    formData.email
                                                }
                                                onChange={
                                                    handleChange
                                                }
                                                placeholder="you@example.com"
                                                autoComplete="email"
                                                required
                                            />
                                        </div>

                                        <div className="form-group">
                                            <label htmlFor="phone">
                                                Phone number
                                            </label>

                                            <input
                                                id="phone"
                                                name="phone"
                                                type="tel"
                                                value={
                                                    formData.phone
                                                }
                                                onChange={
                                                    handleChange
                                                }
                                                placeholder="+90"
                                                autoComplete="tel"
                                                required
                                            />
                                        </div>
                                    </div>

                                    <h2 className="checkout-section-title">
                                        Shipping address
                                    </h2>

                                    <div className="form-row">
                                        <div className="form-group">
                                            <label htmlFor="country">
                                                Country
                                            </label>

                                            <input
                                                id="country"
                                                name="country"
                                                type="text"
                                                value={
                                                    formData.country
                                                }
                                                onChange={
                                                    handleChange
                                                }
                                                placeholder="Türkiye"
                                                autoComplete="country-name"
                                                required
                                            />
                                        </div>

                                        <div className="form-group">
                                            <label htmlFor="city">
                                                City
                                            </label>

                                            <input
                                                id="city"
                                                name="city"
                                                type="text"
                                                value={
                                                    formData.city
                                                }
                                                onChange={
                                                    handleChange
                                                }
                                                placeholder="Kayseri"
                                                autoComplete="address-level2"
                                                required
                                            />
                                        </div>
                                    </div>

                                    <div className="form-group">
                                        <label htmlFor="address">
                                            Full address
                                        </label>

                                        <input
                                            id="address"
                                            name="address"
                                            type="text"
                                            value={
                                                formData.address
                                            }
                                            onChange={
                                                handleChange
                                            }
                                            placeholder="Street, building and apartment"
                                            autoComplete="street-address"
                                            required
                                        />
                                    </div>

                                    <div className="form-group">
                                        <label htmlFor="postalCode">
                                            Postal code
                                        </label>

                                        <input
                                            id="postalCode"
                                            name="postalCode"
                                            type="text"
                                            value={
                                                formData.postalCode
                                            }
                                            onChange={
                                                handleChange
                                            }
                                            placeholder="38000"
                                            autoComplete="postal-code"
                                            required
                                        />
                                    </div>

                                    <h2 className="checkout-section-title">
                                        Payment information
                                    </h2>

                                    <div className="form-group">
                                        <label htmlFor="cardName">
                                            Name on card
                                        </label>

                                        <input
                                            id="cardName"
                                            name="cardName"
                                            type="text"
                                            value={
                                                formData.cardName
                                            }
                                            onChange={
                                                handleChange
                                            }
                                            placeholder="Cardholder name"
                                            autoComplete="cc-name"
                                            required
                                        />
                                    </div>

                                    <div className="form-group">
                                        <label htmlFor="cardNumber">
                                            Card number
                                        </label>

                                        <input
                                            id="cardNumber"
                                            name="cardNumber"
                                            type="text"
                                            inputMode="numeric"
                                            value={
                                                formData.cardNumber
                                            }
                                            onChange={
                                                handleChange
                                            }
                                            placeholder="0000 0000 0000 0000"
                                            autoComplete="cc-number"
                                            maxLength={19}
                                            required
                                        />
                                    </div>

                                    <div className="form-row">
                                        <div className="form-group">
                                            <label htmlFor="expiry">
                                                Expiry date
                                            </label>

                                            <input
                                                id="expiry"
                                                name="expiry"
                                                type="text"
                                                inputMode="numeric"
                                                value={
                                                    formData.expiry
                                                }
                                                onChange={
                                                    handleChange
                                                }
                                                placeholder="MM/YY"
                                                autoComplete="cc-exp"
                                                maxLength={5}
                                                required
                                            />
                                        </div>

                                        <div className="form-group">
                                            <label htmlFor="cvv">
                                                CVV
                                            </label>

                                            <input
                                                id="cvv"
                                                name="cvv"
                                                type="password"
                                                inputMode="numeric"
                                                value={
                                                    formData.cvv
                                                }
                                                onChange={
                                                    handleChange
                                                }
                                                placeholder="123"
                                                autoComplete="cc-csc"
                                                maxLength={4}
                                                required
                                            />
                                        </div>
                                    </div>

                                    <div className="checkout-trust-row">
                                        <span className="trust-pill">
                                            <span className="trust-dot" />
                                            Secure checkout
                                        </span>

                                        <span className="trust-pill">
                                            <span className="trust-dot" />
                                            Free shipping
                                        </span>

                                        <span className="trust-pill">
                                            <span className="trust-dot" />
                                            30-day guarantee
                                        </span>
                                    </div>

                                    <button
                                        type="submit"
                                        className="checkout-confirm"
                                        disabled={
                                            items.length ===
                                            0
                                        }
                                    >
                                        Confirm pre-order ·{" "}
                                        {formatPrice(
                                            total
                                        )}
                                    </button>
                                </form>
                            </section>

                            <aside className="checkout-card premium-summary-card summary-card">
                                <div className="summary-header">
                                    <h3>
                                        Your order
                                    </h3>

                                    <span>
                                        {count}{" "}
                                        {count === 1
                                            ? "item"
                                            : "items"}
                                    </span>
                                </div>

                                {items.length === 0 ? (
                                    <div className="empty-cart">
                                        <p>
                                            Your cart is
                                            currently empty.
                                        </p>

                                        <Link
                                            to="/products"
                                            className="primary-cta"
                                        >
                                            Browse products
                                        </Link>
                                    </div>
                                ) : (
                                    <>
                                        <div className="cart-list premium-cart-list">
                                            {items.map(
                                                (item) => (
                                                    <article
                                                        key={
                                                            item.id
                                                        }
                                                        className="cart-item premium-cart-item"
                                                    >
                                                        <div className="cart-thumb">
                                                            <img
                                                                src={resolveImage(
                                                                    item.image
                                                                )}
                                                                alt={
                                                                    item.title
                                                                }
                                                            />
                                                        </div>

                                                        <div className="cart-content">
                                                            <p className="cart-name">
                                                                {
                                                                    item.title
                                                                }
                                                            </p>

                                                            <p className="cart-meta">
                                                                {
                                                                    item.variant
                                                                }
                                                            </p>

                                                            <div className="cart-controls">
                                                                <label className="qty">
                                                                    Qty

                                                                    <input
                                                                        type="number"
                                                                        min="1"
                                                                        value={
                                                                            item.quantity ||
                                                                            1
                                                                        }
                                                                        onChange={(
                                                                            event
                                                                        ) =>
                                                                            updateQuantity(
                                                                                item.id,
                                                                                event
                                                                                    .target
                                                                                    .value
                                                                            )
                                                                        }
                                                                    />
                                                                </label>

                                                                <button
                                                                    type="button"
                                                                    className="link-danger"
                                                                    onClick={() =>
                                                                        removeItem(
                                                                            item.id
                                                                        )
                                                                    }
                                                                >
                                                                    Remove
                                                                </button>
                                                            </div>
                                                        </div>

                                                        <div className="cart-price">
                                                            {formatPrice(
                                                                Number(
                                                                    item.price
                                                                ) *
                                                                (item.quantity ||
                                                                    1)
                                                            )}
                                                        </div>
                                                    </article>
                                                )
                                            )}
                                        </div>

                                        <div className="cart-bottom">
                                            <button
                                                type="button"
                                                className="link-danger"
                                                onClick={
                                                    clearCart
                                                }
                                            >
                                                Clear cart
                                            </button>
                                        </div>
                                    </>
                                )}

                                <div className="summary-divider" />

                                <div className="summary-row">
                                    <span>
                                        Subtotal
                                    </span>

                                    <strong>
                                        {formatPrice(
                                            subtotal
                                        )}
                                    </strong>
                                </div>

                                <div className="summary-row">
                                    <span>
                                        Shipping
                                    </span>

                                    <strong>
                                        Free
                                    </strong>
                                </div>

                                <div className="summary-divider" />

                                <div className="summary-row total">
                                    <span>
                                        Total
                                    </span>

                                    <strong>
                                        {formatPrice(
                                            total
                                        )}
                                    </strong>
                                </div>

                                <p className="summary-note">
                                    Your payment information
                                    is entered through this
                                    checkout form. Connect the
                                    submit handler to your real
                                    payment provider before
                                    publishing the store.
                                </p>
                            </aside>
                        </div>
                    )}
                </div>
            </main>
        </div>
    );
}