// src/Specs.js

import React, {
    useEffect,
    useMemo,
    useState,
} from "react";

import { Link } from "react-router-dom";

import "./App.css";

import { PRODUCTS, asset } from "./productsData";
import SiteHeader from "./SiteHeader";

function SpecsIntro() {
    const [visible, setVisible] =
        useState(true);

    useEffect(() => {
        const timer = window.setTimeout(
            () => setVisible(false),
            900
        );

        return () => {
            window.clearTimeout(timer);
        };
    }, []);

    if (!visible) return null;

    return (
        <div
            className="specs-intro"
            aria-hidden="true"
        >
            <div className="specs-intro-bg" />
            <div className="specs-intro-ring" />
            <div className="specs-intro-logo">
                IDEAL.
            </div>
        </div>
    );
}

const featureCards = [
    {
        title: "UV400 Protection",
        description:
            "Built to block harmful ultraviolet light during daily outdoor use.",
    },
    {
        title: "Anti-Glare Optics",
        description:
            "A multi-layer lens coating helps reduce harsh reflections and visual distraction.",
    },
    {
        title: "48g Lightweight",
        description:
            "Balanced weight distribution supports long periods of comfortable wear.",
    },
    {
        title: "Premium Hinge",
        description:
            "A durable hinge system provides controlled movement and a solid premium feel.",
    },
];

const specificationGroups = [
    {
        title: "Frame",
        rows: [
            {
                label: "Frame material",
                value:
                    "Lightweight premium composite",
            },
            {
                label: "Frame finish",
                value:
                    "Matte low-reflection finish",
            },
            {
                label: "Weight",
                value: "Approximately 48 g",
            },
            {
                label: "Fit",
                value:
                    "Balanced medium universal fit",
            },
            {
                label: "Hinge",
                value:
                    "Reinforced smooth-action hinge",
            },
        ],
    },
    {
        title: "Lenses",
        rows: [
            {
                label: "Protection",
                value: "UV400 protection",
            },
            {
                label: "Coating",
                value:
                    "Triple anti-reflective coating",
            },
            {
                label: "Glare control",
                value:
                    "Reduced harsh reflections",
            },
            {
                label: "Visual profile",
                value:
                    "Deep contrast with neutral clarity",
            },
            {
                label: "Surface",
                value:
                    "Scratch-resistant treated surface",
            },
        ],
    },
    {
        title: "Measurements",
        rows: [
            {
                label: "Lens width",
                value: "Approximately 52 mm",
            },
            {
                label: "Bridge width",
                value: "Approximately 19 mm",
            },
            {
                label: "Temple length",
                value: "Approximately 145 mm",
            },
            {
                label: "Frame width",
                value: "Approximately 140 mm",
            },
            {
                label: "Lens height",
                value: "Approximately 43 mm",
            },
        ],
    },
    {
        title: "Package",
        rows: [
            {
                label: "Eyewear",
                value:
                    "One IDEAL premium frame",
            },
            {
                label: "Case",
                value:
                    "Protective carrying case",
            },
            {
                label: "Cleaning",
                value:
                    "Premium microfiber cloth",
            },
            {
                label: "Packaging",
                value:
                    "IDEAL branded presentation box",
            },
            {
                label: "Guarantee",
                value:
                    "30-day comfort guarantee",
            },
        ],
    },
];

export default function Specs() {
    const product = PRODUCTS[0];

    const heroImage = useMemo(() => {
        const frontImage =
            product?.gallery?.find(
                (item) => item.id === "front"
            );

        return (
            frontImage?.src ||
            product?.suggestionImage ||
            "/01_front_view.png"
        );
    }, [product]);

    useEffect(() => {
        window.scrollTo({
            top: 0,
            left: 0,
            behavior: "auto",
        });
    }, []);

    return (
        <div
            className="page specs-page"
            style={{
                background:
                    "radial-gradient(circle at top, #292929 0%, #070707 58%, #000 100%)",
            }}
        >
            <SpecsIntro />

            <SiteHeader overlay />

            <div className="tech-grid-overlay product-grid" />

            <main className="specs-main">
                <div className="container">
                    <section className="specs-hero">
                        <div className="specs-hero-copy">
                            <p className="eyebrow">
                                TECHNICAL SPECIFICATIONS
                            </p>

                            <h1 className="specs-title">
                                Built for clarity.{" "}
                                <span>
                                    Designed for comfort.
                                </span>
                            </h1>

                            <p className="specs-subtitle">
                                Explore the frame,
                                measurements, optical
                                protection, materials, and
                                included accessories of the
                                IDEAL 2026 collection.
                            </p>

                            <div className="specs-actions">
                                <Link
                                    to={`/product/${product?.id ||
                                        "classic"
                                        }?view=front`}
                                    className="primary-cta"
                                >
                                    View product
                                </Link>

                                <Link
                                    to="/checkout"
                                    className="secondary-cta"
                                >
                                    Pre-order now
                                </Link>
                            </div>
                        </div>

                        <div className="specs-hero-card glass-card">
                            <img
                                src={asset(heroImage)}
                                alt="IDEAL eyewear front view"
                                className="specs-hero-image"
                            />
                        </div>
                    </section>

                    <section className="specs-features">
                        <div className="specs-section-head">
                            <p className="eyebrow">
                                CORE TECHNOLOGY
                            </p>

                            <h2>
                                Engineered around everyday vision.
                            </h2>
                        </div>

                        <div className="specs-feature-grid">
                            {featureCards.map(
                                (feature) => (
                                    <article
                                        key={
                                            feature.title
                                        }
                                        className="specs-feature-card glass-card"
                                    >
                                        <div className="specs-feature-dot" />

                                        <h3>
                                            {
                                                feature.title
                                            }
                                        </h3>

                                        <p>
                                            {
                                                feature.description
                                            }
                                        </p>
                                    </article>
                                )
                            )}
                        </div>
                    </section>

                    <section className="specs-table-section">
                        <div className="specs-section-head">
                            <p className="eyebrow">
                                COMPLETE DETAILS
                            </p>

                            <h2>
                                Product specifications.
                            </h2>
                        </div>

                        <div className="specs-groups">
                            {specificationGroups.map(
                                (group) => (
                                    <article
                                        key={
                                            group.title
                                        }
                                        className="specs-group glass-card"
                                    >
                                        <header className="specs-group-head">
                                            <h3>
                                                {
                                                    group.title
                                                }
                                            </h3>
                                        </header>

                                        <div className="specs-rows">
                                            {group.rows.map(
                                                (row) => (
                                                    <div
                                                        key={
                                                            row.label
                                                        }
                                                        className="specs-row"
                                                    >
                                                        <span className="specs-label">
                                                            {
                                                                row.label
                                                            }
                                                        </span>

                                                        <span className="specs-value">
                                                            {
                                                                row.value
                                                            }
                                                        </span>
                                                    </div>
                                                )
                                            )}
                                        </div>
                                    </article>
                                )
                            )}
                        </div>
                    </section>

                    <section className="specs-cta">
                        <div className="specs-cta-card glass-card">
                            <p className="eyebrow">
                                IDEAL 2026 COLLECTION
                            </p>

                            <h2>
                                Ready to experience sharper vision?
                            </h2>

                            <p>
                                Explore every product angle,
                                select your preferred style,
                                and complete your IDEAL
                                pre-order securely.
                            </p>

                            <div
                                className="specs-actions"
                                style={{
                                    justifyContent:
                                        "center",
                                }}
                            >
                                <Link
                                    to="/products"
                                    className="secondary-cta"
                                >
                                    Browse collection
                                </Link>

                                <Link
                                    to="/checkout"
                                    className="primary-cta"
                                >
                                    Pre-order now
                                </Link>
                            </div>
                        </div>
                    </section>
                </div>
            </main>

            <footer className="site-footer">
                <div className="container footer-inner">
                    <div className="footer-left">
                        <Link
                            to="/"
                            className="footer-logo"
                            style={{
                                color: "inherit",
                                textDecoration: "none",
                            }}
                        >
                            IDEAL.
                        </Link>

                        <span className="footer-copy">
                            © 2026 IDEAL. All rights
                            reserved.
                        </span>
                    </div>

                    <nav
                        className="nav-links"
                        aria-label="Footer navigation"
                    >
                        <Link to="/products">
                            Products
                        </Link>

                        <Link to="/specs">
                            Specs
                        </Link>

                        <Link to="/checkout">
                            Pre-order
                        </Link>
                    </nav>
                </div>
            </footer>
        </div>
    );
}