// src/Products.js

import React, {
    useEffect,
    useState,
} from "react";

import {
    Link,
} from "react-router-dom";

import "./App.css";

import SiteHeader from "./SiteHeader";

import {
    PRODUCTS,
    asset,
} from "./productsData";


/* =========================================================
   PRODUCTS PAGE INTRO
========================================================= */

function ProductsPageIntro() {
    const [visible, setVisible] =
        useState(true);

    const [isLeaving, setIsLeaving] =
        useState(false);

    useEffect(() => {
        const previousOverflow =
            document.body.style.overflow;

        document.body.style.overflow =
            "hidden";

        const leaveTimer =
            window.setTimeout(() => {
                setIsLeaving(true);
            }, 950);

        const removeTimer =
            window.setTimeout(() => {
                setVisible(false);

                document.body.style.overflow =
                    previousOverflow;
            }, 1450);

        return () => {
            window.clearTimeout(
                leaveTimer
            );

            window.clearTimeout(
                removeTimer
            );

            document.body.style.overflow =
                previousOverflow;
        };
    }, []);

    if (!visible) {
        return null;
    }

    return (
        <div
            className={`products-page-intro ${isLeaving
                    ? "is-leaving"
                    : ""
                }`}
            aria-hidden="true"
        >
            <div className="products-page-intro-bg" />

            <div className="products-intro-ring products-intro-ring-one" />

            <div className="products-intro-ring products-intro-ring-two" />

            <div className="products-page-intro-content">
                <span className="products-intro-small">
                    2026 COLLECTION
                </span>

                <div className="products-page-intro-logo">
                    IDEAL.
                </div>

                <span className="products-intro-line" />
            </div>
        </div>
    );
}


/* =========================================================
   PRODUCT CARD
========================================================= */

function ProductCard({
    product,
}) {
    const productUrl =
        `/product/${product.id}?view=front`;

    const productTitle =
        product.label ||
        product.name ||
        product.productTitle ||
        "IDEAL Eyewear";

    const productDescription =
        product.suggestionDesc ||
        product.productTagline ||
        product.detailDesc ||
        "";

    const productImage =
        product.suggestionImage ||
        product.gallery?.[0]?.src ||
        "";

    return (
        <article className="suggestion-card glass-card">
            <Link
                to={productUrl}
                className="product-card-image-link"
                aria-label={`Open ${productTitle}`}
            >
                {productImage && (
                    <img
                        src={asset(
                            productImage
                        )}
                        alt={productTitle}
                        loading="lazy"
                    />
                )}
            </Link>

            <div className="suggestion-body">
                {product.sku && (
                    <p className="product-card-sku">
                        {product.sku}
                    </p>
                )}

                <h4>
                    <Link
                        to={productUrl}
                        className="product-card-title-link"
                    >
                        {productTitle}
                    </Link>
                </h4>

                <p>
                    {productDescription}
                </p>

                <div className="suggestion-meta">
                    <span>
                        ${product.price}
                    </span>

                    <Link
                        to={productUrl}
                        className="suggestion-view"
                    >
                        View product
                    </Link>
                </div>
            </div>
        </article>
    );
}


